import { JSXElement, ParentComponent } from "solid-js";

import { Header } from "#core/ui-next/components/header.jsx";

export interface BorderPanelProps {
	title: JSXElement;
	class?: string;
}

export const BorderPanel: ParentComponent<BorderPanelProps> = (props) => {
	return (
		<div class={`img-dropdown-box m-2 p-4 flex flex-col justify-start ${props.class ?? ""}`}>
			<Header class="mb-2">{props.title}</Header>
			{props.children}
		</div>
	);
};
